# 8 - Sectiunea 3
from functools import reduce
n = int(input()) # nr pt care aplic factorial
def inmultire(a, b):
    return a*b
# reducere(_, l)
# def f(a, c); a - acumulator, default = 0
# cu al treilea parametru la reduce pot schimba default la acumulator
fac = reduce(inmultire, range(1,n+1))
print(fac)

