# 13 - Sectiunea 4
import math
def dist_euclidiana(A: tuple, B: tuple) -> float:
    return math.sqrt((B[0]-A[0])**2 + (B[1]-A[1])**2) # math.dist()
print(dist_euclidiana((1,2),(5,6)))

